/** The server's group snapshot (snake_case, from get_group / list_groups / api_group_state). */
export interface WireGroupSnapshot {
  rev: string;
  group: WithVersion<WireGroup>;
  members: WithVersion<WireMember>[];
  expenses: WithVersion<WireExpense>[];
  settlements: WithVersion<WireSettlement>[];
  recurring_rules: WithVersion<WireRecurringRule>[];
  currency_locked: boolean;
  rules_with_occurrences: string[];
}

export function snapshotFromWire(w: WireGroupSnapshot): GroupSnapshot {
  return {
    rev: String(w.rev),
    group: groupFromWire(w.group),
    members: (w.members ?? []).map(memberFromWire).sort((a, b) => a.createdAt - b.createdAt || (a.id < b.id ? -1 : 1)),
    expenses: (w.expenses ?? []).map(expenseFromWire).sort(compareExpensesNewestFirst),
    settlements: (w.settlements ?? []).map(settlementFromWire).sort((a, b) => b.settledAt - a.settledAt),
    rules: (w.recurring_rules ?? []).map(ruleFromWire).sort((a, b) => a.createdAt - b.createdAt),
    currencyLocked: w.currency_locked === true,
    rulesWithOccurrences: (w.rules_with_occurrences ?? []).map(lower),
  };
}
